from decimal import Decimal, ROUND_HALF_UP

__all__ = ["to_iso", "from_iso", "yn", "to_minor_units"]

_LEGACY_NULL_DATE = "00000000"


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD, preserving null semantics."""
    if yyyymmdd in (None, "", _LEGACY_NULL_DATE):
        return None
    return f"{yyyymmdd[:4]}-{yyyymmdd[4:6]}-{yyyymmdd[6:]}"


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to the legacy YYYYMMDD representation."""
    if iso in (None, ""):
        return _LEGACY_NULL_DATE
    return iso.replace("-", "")


def yn(char: str | None) -> bool:
    """Convert the legacy Y/N flag, where blank has the same meaning as N."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to integer currency minor units.

    JPY uses zero decimal places; all other currencies use two. Conversion uses
    Decimal and legacy half-up rounding rather than binary floating-point math.
    """
    if amount is None or amount == "":
        return 0

    currency_code = (currency or "USD").strip().upper() or "USD"
    exponent = 0 if currency_code == "JPY" else 2
    scaled = Decimal(str(amount)) * (Decimal(10) ** exponent)

    return int(scaled.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
